__NUXT_JSONP__("/th/promo_material/thanks", (function(a){return {data:[{details:{slug:"th",pageTitle:"Promo - Thanks Download Brochure | Mentor Language Institute",pageDescription:"กรุณาดาวน์โหลดแผ่นพับโดยใช้ลิงค์ด้านล่าง",title:"Promo - Thanks Download Brochure",subtitle:["กรุณาดาวน์โหลดแผ่นพับโดยใช้ลิงค์ด้านล่าง:"],brochures:[{title:"โปรโมชั่นต้อนรับปี 2022",image:"\u002Fimages\u002Fmaterial\u002F1643410547-WELCOME_Promotion_THAI_JAN19.jpg",link_text:a,link:"\u002Fassets\u002Fimages\u002Fmaterial\u002F1643410547-WELCOME_Promotion_THAI_JAN19.jpg"},{title:"แผ่นพับเกี่ยวกับโรงเรียน",image:"\u002Fimages\u002Fmaterial\u002Fmli-brochure-program-schedule-en.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FMLI School Brochure.pdf"},{title:"แผ่นพับเกี่ยวกับที่พัก",image:"\u002Fimages\u002Fmaterial\u002F2022-housing-brochure.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FUSSS Student Housing Brochure(updated 10.16.2024).pdf"},{title:"2026 ราคาและการลงทะเบียน",image:"\u002Fimages\u002Fmaterial\u002F2026-price-package.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2026 MLI Info Pack updated_9.17.25.pdf"},{title:"โบรชัวร์กิจกรรมของ MLI",image:"\u002Fimages\u002Fmaterial\u002F2027 MLI Activity.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2027 MLI Activity Calendar Brochure 10.1.26.pdf"}],other_info:["\u003Cspan class='hutoaka'\u003Eเจ้าหน้าที่รับสมัครจะส่งอีเมลถึงคุณเกี่ยวกับการสอบถามของคุณ\u003C\u002Fspan\u003E\u003Cbr \u002F\u003Eหากคุณมีคำถามใดๆ เกี่ยวกับวีซ่านักเรียน ความพร้อมในการอยู่อาศัย หรือสิ่งอื่นใด โปรดติดต่อเราได้ตลอดเวลา","ขั้นตอนการเรียนต่อต่างประเทศในสหรัฐอเมริกานั้นซับซ้อนมาก เราสามารถแนะนำขั้นตอนต่าง ๆ ให้คุณได้ทางโทรศัพท์","หากคุณไม่ได้เลือก \"อย่าติดต่อฉันทางโทรศัพท์\" เราจะโทรหาคุณในหนึ่งหรือสองวัน","\u003Cb\u003E【วิทยาเขตเวสต์วูด】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E10880 Wilshire Blvd., Suite 122\u003Cbr \u002F\u003ELos Angeles, CA 90024\u003Cbr \u002F\u003ETEL: ＋1（310）887-0777\u003Cbr \u002F\u003EE-mail: info@mliesl.edu\u003Cbr \u002F\u003Eเวลาทำการ: วันจันทร์ถึงวันพฤหัสบดี 8:30 – 20:30 น. วันศุกร์ 8:30 – 18:00 น.","\u003Cb\u003E【วิทยาเขตฮอลลีวูด】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E7080 Hollywood Blvd., Suite 314\u003Cbr \u002F\u003ELos Angeles, CA 90028\u003Cbr \u002F\u003ETEL: ＋1（323）870-7102\u003Cbr \u002F\u003EE-mail: hollywood@mliesl.edu\u003Cbr \u002F\u003Eเวลาทำการ : จันทร์-ศุกร์ 8:30-17:00 น."],dir:"\u002Fpromo-material-thanks",path:"\u002Fpromo-material-thanks\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.789Z",updatedAt:"2026-10-06T17:46:57.888Z"}}],fetch:{},mutations:void 0}}("\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Download")));